QUESTIONS = {
    41: [
        ("BEGINNER", "Which interactive command-line tool is the standard terminal front-end for PostgreSQL?", ["psql", "pgAdmin", "pg_dump", "postmaster"], "A", "psql is the official interactive client that lets you run SQL against PostgreSQL from a terminal."),
        ("BEGINNER", "From inside psql, which meta-command shows all databases (typed as a backslash followed by a letter)?", ["backslash d", "backslash l", "backslash q", "backslash s"], "B", "The backslash-l meta-command is short for list and displays every database with its owner and encoding."),
        ("BEGINNER", "Which statement creates a new empty database called inventory?", ["ADD DATABASE inventory;", "NEW DATABASE inventory;", "CREATE DATABASE inventory;", "MAKE DB inventory;"], "C", "CREATE DATABASE inventory; is the standard SQL statement for creating a new database."),
        ("BEGINNER", "What is the default superuser role name created by a standard PostgreSQL installation?", ["admin", "root", "super", "postgres"], "D", "postgres is the default superuser role created during installation, owning the server's administrative privileges."),
        ("BEGINNER", "Which SQL command permanently removes a database named olddb?", ["DROP DATABASE olddb;", "DELETE DATABASE olddb;", "REMOVE DATABASE olddb;", "TRUNCATE DATABASE olddb;"], "A", "DROP DATABASE removes the database and all of its objects, whereas DELETE and TRUNCATE only act on table rows."),
        ("BEGINNER", "Which statement begins a transaction that can later be committed or rolled back?", ["COMMIT;", "BEGIN;", "SAVEPOINT;", "ROLLBACK;"], "B", "BEGIN; starts a new transaction block whose changes are made permanent only when a COMMIT is issued."),
        ("BEGINNER", "A schema in PostgreSQL is used primarily for what purpose?", ["storing passwords", "backing up data", "grouping objects such as tables and functions into a namespace", "storing connection settings"], "C", "A schema is a namespace that organizes database objects and lets multiple applications share one database with isolated name spaces."),
        ("BEGINNER", "Which psql meta-command lists the tables in the current database (typed as a backslash followed by letters)?", ["backslash l", "backslash q", "backslash d", "backslash dt"], "D", "backslash dt is the meta-command that lists the tables of the current schema, standing for describe table."),
        ("BEGINNER", "Which of the following is a valid way to connect psql to a database named app on port 5432?", ["psql -d app -p 5432", "psql app --port", "psql -p app -d 5432", "connect app"], "A", "psql -d app -p 5432 selects database app with the -d flag and the listening port 5432 with the -p flag."),
        ("BEGINNER", "What does the command GRANT SELECT ON books TO reader; do?", ["denies the reader role all access", "gives the reader role permission to run SELECT queries on books", "deletes the books table", "creates a new role named reader"], "B", "GRANT SELECT ON books TO reader; adds the SELECT privilege on books for the reader role, letting it query the table."),
        ("INTERMEDIATE", "After running CREATE ROLE clerk; a user named clerk tries to log in. Why might the login fail?", ["the password is too short", "the database is full", "the role does not have the LOGIN attribute", "the role has no schema"], "C", "A role created with plain CREATE ROLE gets no LOGIN attribute, so it cannot authenticate to a server session."),
        ("INTERMEDIATE", "You run ALTER ROLE alice CREATEDB; What does alice gain?", ["the ability to drop any database", "a new password", "superuser rights", "the ability to create new databases"], "D", "CREATEDB is a role attribute that lets the role create databases, though it cannot grant that attribute to others."),
        ("INTERMEDIATE", "Which psql meta-command lists all schemas in the current database (typed as a backslash followed by letters)?", ["backslash dn", "backslash dt", "backslash dv", "backslash di"], "A", "backslash dn lists the schemas of the current database, which are the top-level namespaces that hold database objects."),
        ("INTERMEDIATE", "Why might CREATE DATABASE fail with the message role does not have permission?", ["the server is offline", "the current role lacks the CREATEDB attribute", "the database name has uppercase letters", "the default tablespace is missing"], "B", "Creating a database requires the CREATEDB privilege, so a role without that attribute cannot run CREATE DATABASE."),
        ("INTERMEDIATE", "Which of these is NOT true about the public schema?", ["it exists by default in every database", "its objects are visible to everyone by default", "it can be dropped", "it can hold only tables"], "C", "The public schema can hold tables, views, functions and many other object kinds, so claiming it holds only tables is false."),
        ("INTERMEDIATE", "What happens when you run DROP DATABASE while another session is connected to that database?", ["the database is dropped immediately", "only the active session is dropped", "the command waits until the session ends", "the command fails with an error about active connections"], "D", "PostgreSQL refuses to drop a database with open connections and raises an error saying the database is being accessed by other users."),
        ("INTERMEDIATE", "Which statement gives role auditor the right to INSERT rows into table log?", ["GRANT INSERT ON log TO auditor;", "ALLOW INSERT TO auditor ON log;", "CREATE INSERT log auditor;", "PRIVILEGE INSERT ON log auditor;"], "A", "GRANT INSERT ON log TO auditor; adds the INSERT privilege on log for role auditor."),
        ("INTERMEDIATE", "What does REVOKE SELECT ON books FROM clerk; accomplish?", ["removes the clerk role", "removes clerk ability to read books", "removes the books table", "makes clerk a superuser"], "B", "REVOKE SELECT removes the previously granted SELECT privilege, so clerk can no longer query the books table."),
        ("INTERMEDIATE", "Which database attribute can you change with ALTER DATABASE app OWNER TO dba;?", ["character encoding", "connection limit", "ownership", "tablespace"], "C", "ALTER DATABASE ... OWNER TO changes the role that owns the database, which controls who may drop or rename it."),
        ("INTERMEDIATE", "The search_path setting influences what when you write an unqualified table name in a query?", ["query performance", "transaction isolation", "the table owner", "which schema PostgreSQL looks in for the table"], "D", "search_path lists the schemas searched in order for unqualified object names, defaulting to the current user schema and then public."),
        ("ADVANCED", "A backup made with pg_dump mydb > mydb.sql is being restored with psql mydb < mydb.sql. What is missing from this procedure?", ["nothing", "the psql restore cannot create roles that do not already exist on the target server", "the target database must be dropped first", "pg_dump output is binary only"], "B", "A plain-text dump recreates tables and data, but role creation needs superuser privileges, so restoring fails when the referenced roles do not exist on the target."),
        ("ADVANCED", "You restore a custom-format dump with pg_restore. Which flag tells it to drop existing objects before recreating them?", ["--create", "--verbose", "--clean", "--single-transaction"], "C", "The --clean (or -c) flag makes pg_restore issue DROP statements for objects before recreating them."),
        ("ADVANCED", "Why might you use pg_restore with a custom-format dump instead of psql with a plain text dump?", ["custom format is smaller only", "plain dumps cannot restore data", "psql cannot read SQL files", "you can selectively restore objects and run restores in parallel"], "D", "Custom-format dumps support selective object restoration, parallel jobs and interactive listing, which plain SQL dumps do not."),
        ("ADVANCED", "A role named app is a member of role readonly, which has SELECT on books. What must be true for app to query books?", ["app inherits readonly privileges by default", "app must be superuser", "readonly must be dropped", "app needs a password"], "A", "By default roles inherit the privileges of the roles they belong to (INHERIT), so app can SELECT books through readonly."),
        ("ADVANCED", "You create schema analytics owned by role etl. Why can a superuser-backed application still read it without an explicit GRANT?", ["schemas are public by default", "superusers bypass all privilege checks", "GRANT is only used for tables", "the application has a password"], "B", "Superusers are exempt from normal privilege checks and can access any object in any schema without a GRANT."),
        ("ADVANCED", "Which is the correct element order for a local connection rule in a pg_hba.conf authentication file?", ["host, database, user, address, method", "method, user, database, address", "local, database, user, auth-method", "user, database, host, method"], "C", "pg_hba.conf lines begin with the connection type, then database, then user, and end with the authentication method for local lines."),
        ("ADVANCED", "What is a template database used for in PostgreSQL?", ["storing backups", "indexing", "encryption", "serving as the model that new databases are copied from"], "D", "template1 (and the pristine template0) is copied when a new database is created, so objects added to template1 appear in every new database."),
        ("ADVANCED", "You set ALTER ROLE app CONNECTION LIMIT 5; what does it limit?", ["how many simultaneous connections app may open", "the number of databases app owns", "the queries app may run per second", "the size of result sets"], "A", "CONNECTION LIMIT caps the number of concurrent server connections a role may use, with a value of -1 meaning unlimited."),
        ("ADVANCED", "What is the effect of CREATE DATABASE fresh TEMPLATE template0;?", ["template0 is dropped", "fresh starts from a pristine base free of local template1 customizations", "fresh has no owner", "fresh is read-only"], "B", "Using TEMPLATE template0 builds a clean database that excludes any custom objects that were added to template1."),
        ("ADVANCED", "Which approach cleanly renames a database that currently has active connections?", ["drop the database and recreate it", "ALTER DATABASE ... RENAME inside a transaction", "terminate the connections first, then ALTER DATABASE ... RENAME", "restore from a backup"], "C", "RENAME fails while connections are open, so you must terminate the sessions first, for example with pg_terminate_backend, before renaming."),
    ],
    42: [
        ("BEGINNER", "Which PostgreSQL data type generates an auto-incrementing integer column when used as a column type?", ["SERIAL", "FLOAT", "TEXT", "BOOLEAN"], "A", "SERIAL is a pseudo-type that creates an integer column backed by a sequence, auto-filling each new row."),
        ("BEGINNER", "In NUMERIC(8,2), what do the numbers 8 and 2 mean?", ["8 bytes total with 2 bytes of fraction", "8 total digits with exactly 2 digits after the decimal point", "8 digits before the decimal point", "8 percent precision"], "B", "NUMERIC(8,2) stores up to 8 significant digits with exactly 2 digits after the decimal point."),
        ("BEGINNER", "Which type should you choose for an exact currency amount to avoid floating-point rounding?", ["REAL", "DOUBLE PRECISION", "NUMERIC", "INTEGER"], "C", "NUMERIC is an exact arbitrary-precision type, so it avoids the rounding errors of floating-point REAL and DOUBLE PRECISION."),
        ("BEGINNER", "What is the main purpose of the UUID data type in PostgreSQL?", ["increasing performance", "saving disk space", "storing globally unique identifiers", "sorting text faster"], "D", "The UUID type stores 128-bit universally unique identifiers, which is useful when ids must be unique across separate systems."),
        ("BEGINNER", "Which constraint guarantees that a column must have a value in every row?", ["NOT NULL", "DEFAULT", "CHECK", "INDEX"], "A", "NOT NULL rejects NULL values, requiring every row to hold a value in that column."),
        ("BEGINNER", "What does a PRIMARY KEY constraint guarantee about a column?", ["values are random", "each value is unique and not null", "values are alphabetical", "only one table can reference it"], "B", "A PRIMARY KEY combines UNIQUE and NOT NULL, and each table can have at most one primary key."),
        ("BEGINNER", "Which data type stores a string padded to exactly n characters?", ["TEXT", "VARCHAR(n)", "CHAR(n)", "TEXT(n)"], "C", "CHAR(n) is a fixed-length character type that pads stored values with blanks to the declared length n."),
        ("BEGINNER", "What does the UNIQUE constraint do to a column?", ["prevents reads", "removes duplicate rows", "adds an index only", "rejects duplicate values in that column"], "D", "UNIQUE forbids two rows from sharing the same value in the constrained column, and it builds a supporting index automatically."),
        ("BEGINNER", "Which constraint verifies that a column value satisfies an expression such as price > 0?", ["CHECK", "FOREIGN KEY", "DEFAULT", "IDENTITY"], "A", "CHECK enforces that column values satisfy a boolean expression and rejects any row that violates it."),
        ("BEGINNER", "What value is used when you insert a row without specifying a column that has a DEFAULT clause?", ["NULL", "the value from the DEFAULT expression", "the sequence value", "an error"], "B", "The DEFAULT clause supplies the value that is used when the column is omitted from an INSERT statement."),
        ("INTERMEDIATE", "What is the key difference between SERIAL and the SQL-standard IDENTITY column?", ["they are identical", "SERIAL is always faster", "IDENTITY follows the SQL standard and offers separate GENERATED clauses", "IDENTITY cannot be a primary key"], "C", "GENERATED ... AS IDENTITY is the standard-compliant approach, while SERIAL is a legacy PostgreSQL pseudo-type with different sequence ownership semantics."),
        ("INTERMEDIATE", "You declare id INTEGER GENERATED ALWAYS AS IDENTITY. What happens if you try to insert an explicit value into id?", ["it is stored as is", "it is doubled", "it is ignored silently", "an error is raised unless OVERRIDING SYSTEM VALUE is used"], "D", "For GENERATED ALWAYS columns, inserting an explicit value raises an error unless you add OVERRIDING SYSTEM VALUE to the INSERT."),
        ("INTERMEDIATE", "Which of these is the correct range for the INTEGER type in PostgreSQL?", ["-2147483648 to 2147483647", "-32768 to 32767", "0 to 4294967295", "-9223372036854775808 to 9223372036854775807"], "A", "INTEGER is a 32-bit signed type ranging from -2^31 to 2^31-1, while the last range belongs to BIGINT."),
        ("INTERMEDIATE", "Why might 0.1 + 0.2 not equal 0.3 when stored in a REAL column?", ["REAL truncates to integers", "floating-point binary arithmetic cannot represent all decimals exactly", "REAL only stores text", "PostgreSQL rounds only even numbers"], "B", "Floating-point types store binary approximations, so decimal fractions like 0.1 are not exact and sums can drift from the decimal result."),
        ("INTERMEDIATE", "Which statement defines a new enum type with three values?", ["CREATE TYPE mood AS ENUM ('sad','ok','happy');", "CREATE ENUM mood ('sad','ok','happy');", "CREATE TABLE mood ENUM (...);", "ENUM mood sad ok happy;"], "C", "CREATE TYPE ... AS ENUM defines a user-defined enumerated type with a fixed, ordered list of allowed values."),
        ("INTERMEDIATE", "Which of these is NOT accepted as a boolean true value by PostgreSQL?", ["true", "t", "yes", "2"], "D", "PostgreSQL accepts true, t, yes, on and 1 as true, but a bare 2 is not a valid boolean literal."),
        ("INTERMEDIATE", "A column declared product_id INT REFERENCES products(id) creates what kind of constraint?", ["FOREIGN KEY", "CHECK", "UNIQUE", "SERIAL"], "A", "The REFERENCES clause declares a foreign key that links product_id to the primary key of the products table."),
        ("INTERMEDIATE", "How many NULL values may a UNIQUE column contain?", ["none", "an unlimited number", "at most one", "depends on the table size"], "B", "PostgreSQL treats NULLs as distinct for UNIQUE purposes, so a column with a UNIQUE constraint may hold many NULL rows."),
        ("INTERMEDIATE", "What happens if you try to insert a string longer than VARCHAR(5)?", ["it is truncated silently", "it is stored in overflow pages", "an error is raised", "it wraps to the next row"], "C", "VARCHAR(n) enforces the length limit and rejects oversized values with an error, unlike TEXT which has no length cap."),
        ("INTERMEDIATE", "Which of these correctly describes the SMALLINT range in PostgreSQL?", ["-2^31 to 2^31-1", "0 to 65535", "-2^63 to 2^63-1", "-32768 to 32767"], "D", "SMALLINT is a 16-bit signed integer ranging from -32768 to 32767."),
        ("ADVANCED", "You already have an enum type mood and now need to add a new value. Which is the correct way?", ["CREATE TYPE mood AS ENUM ... again", "ALTER TYPE mood ADD VALUE 'ecstatic';", "UPDATE mood SET ...", "INSERT INTO mood ..."], "B", "Adding a value to an existing enum requires ALTER TYPE ... ADD VALUE, which appends it to the end of the enum's ordering."),
        ("ADVANCED", "What is the effect of adding a CHECK constraint as NOT VALID to a very large table?", ["it disables the constraint forever", "it drops the column", "existing rows are not scanned, but new rows are still enforced", "it forces a full table scan"], "C", "Adding a constraint as NOT VALID skips the expensive scan of existing rows while still enforcing it on new data; a later VALIDATE CONSTRAINT can verify old rows."),
        ("ADVANCED", "Why does ALTER TABLE t ALTER COLUMN c TYPE bigint; usually rewrite the table?", ["nothing happens", "the column is renamed", "only the index is rebuilt", "the table is rewritten because the new type needs a different on-disk representation"], "D", "Most ALTER COLUMN TYPE operations rewrite the whole table because the storage format of the column changes."),
        ("ADVANCED", "Which constraint prevents two bookings from covering overlapping time intervals in the same table?", ["EXCLUDE USING gist (room WITH =, during WITH &&)", "CHECK (room <> during)", "UNIQUE (room, during)", "FOREIGN KEY (room)"], "A", "EXCLUDE USING gist with the && overlap operator forbids rows whose ranges overlap, which a plain UNIQUE or CHECK constraint cannot express."),
        ("ADVANCED", "You define a FOREIGN KEY with ON DELETE CASCADE. What happens when the referenced parent row is deleted?", ["the foreign key is removed", "child rows referencing it are deleted automatically", "nothing happens", "the parent row is kept"], "B", "ON DELETE CASCADE propagates the deletion, automatically removing all child rows that reference the deleted parent row."),
        ("ADVANCED", "Why might joining on a UUID column be slower than joining on an INTEGER primary key?", ["UUID is deprecated", "UUIDs cannot be indexed", "UUIDs are 128-bit random values, making indexes larger and less clustered than small integers", "UUID columns are always NULL"], "C", "Random 128-bit UUID keys produce scattered inserts and larger indexes, so lookups and joins are typically slower than with compact sequential integers."),
        ("ADVANCED", "How do you make a foreign key check run only at COMMIT time rather than after every statement?", ["SET FOREIGN_KEY_CHECKS", "use SERIAL", "drop the constraint", "declare it DEFERRABLE INITIALLY DEFERRED"], "D", "A DEFERRABLE INITIALLY DEFERRED constraint defers its check until transaction commit, allowing temporarily inconsistent states mid-transaction."),
        ("ADVANCED", "Which statement converts an INTEGER column to BIGINT while automatically converting existing values?", ["ALTER TABLE t ALTER COLUMN c TYPE bigint;", "UPDATE t SET c = bigint;", "CAST c AS bigint ON t;", "CHANGE c TO bigint IN t;"], "A", "ALTER TABLE ... ALTER COLUMN ... TYPE bigint uses an implicit cast to convert existing values and rebuild the column."),
        ("ADVANCED", "What happens when a SERIAL column's backing sequence reaches its maximum value?", ["it resets to zero", "inserts fail with a sequence exhausted error until the sequence is rebuilt or altered", "it auto-expands to BIGINT", "it starts returning NULL"], "B", "SERIAL uses a plain INTEGER-backed sequence, so once it exceeds the 32-bit maximum, new inserts fail until the sequence is recreated as BIGINT."),
        ("ADVANCED", "Which statement is true about NUMERIC type storage in PostgreSQL?", ["NUMERIC is stored as fixed 8-byte floats", "NUMERIC maxes out at 18 digits", "NUMERIC stores up to 1000 digits of precision with variable storage", "NUMERIC is an alias for REAL"], "C", "NUMERIC is arbitrary precision up to 1000 digits and uses a variable amount of storage depending on the declared scale."),
    ],
    43: [
        ("BEGINNER", "What is the main difference between the json and jsonb data types?", ["jsonb stores a decomposed binary form that supports indexing, while json keeps the raw input text", "jsonb is a string alias", "json is faster for all queries", "there is no difference"], "A", "jsonb stores the document in a decomposed binary format that can be indexed with GIN, while json keeps the exact input text."),
        ("BEGINNER", "Which operator checks whether one jsonb value contains another jsonb value?", ["=", "@>", "<@", "?&"], "B", "The @> operator (contains) returns true when the left jsonb contains the structure and values of the right one."),
        ("BEGINNER", "Which declaration creates a table column that holds an array of integers?", ["price INT ARRAY", "price INT[]", "price ARRAY OF INT", "price INT LIST"], "C", "price INT[] declares a one-dimensional array column whose elements are integers."),
        ("BEGINNER", "Which function appends an element to the end of an array?", ["array_prepend", "array_extend", "array_add", "array_append"], "D", "array_append(array, element) returns the input array with the element added at the end."),
        ("BEGINNER", "Which operator extracts a jsonb field and returns it as jsonb?", ["->", "->>", "#>", "#>>"], "A", "The -> operator pulls a key and returns the value as jsonb, preserving its type."),
        ("BEGINNER", "Which index type is designed for efficient containment and existence queries on jsonb documents?", ["btree", "GIN", "hash only", "no index works on jsonb"], "B", "A GIN index is the standard choice for jsonb containment and existence queries using operators such as @> and ?."),
        ("BEGINNER", "Which operator extracts a jsonb field value as plain text?", ["->", "#>", "->>", "@>"], "C", "The ->> operator extracts a field and casts it to text, which is convenient for comparisons and display."),
        ("BEGINNER", "Which function returns the number of elements in an array?", ["length()", "count()", "array_size()", "cardinality()"], "D", "cardinality(array) returns the total number of elements in the array."),
        ("BEGINNER", "How do you build an array literal with the array constructor in PostgreSQL?", ["ARRAY[1,2,3]", "[1,2,3]", "ARRAY(1,2,3)", "(1,2,3)"], "A", "ARRAY[1,2,3] is the array constructor syntax; the string form '{1,2,3}' is an alternative way to write an array constant."),
        ("BEGINNER", "Which function builds a jsonb object from alternating keys and values?", ["jsonb_make", "jsonb_build_object", "jsonb_object_text", "jsonb_construct"], "B", "jsonb_build_object('a',1,'b',2) constructs a jsonb object from the supplied alternating key and value arguments."),
        ("INTERMEDIATE", "Which operator tests whether a jsonb object contains a given top-level key?", ["@>", "->", "?", "||"], "C", "The ? operator returns true when the jsonb object has the named key at its top level."),
        ("INTERMEDIATE", "You store data in a jsonb column. How do you update a specific key inside the document?", ["INSERT INTO ... ON CONFLICT", "jsonb_merge", "array_append", "jsonb_set(doc, path, value)"], "D", "jsonb_set(doc, '{key}', value, true) replaces the value at the given path, creating the key when the fourth argument is true."),
        ("INTERMEDIATE", "Which pair of operators checks whether a jsonb object has ANY or ALL of a list of keys?", ["?| and ?&", "@> and <@", "-> and ->>", "#- and #>"], "A", "The ?| operator checks whether any listed key exists, while ?& requires all listed keys to exist."),
        ("INTERMEDIATE", "Given a jsonb column data holding an object with a name key, which expression returns the name value as plain text?", ["data -> 'name'", "data ->> 'name'", "data #> 'name'", "data @> 'name'"], "B", "The ->> operator extracts the name field as text, giving the readable string value."),
        ("INTERMEDIATE", "Which function expands an array into one row per element?", ["array_to_string", "array_agg", "unnest", "array_prepend"], "C", "unnest(array) turns each array element into a separate row, which is useful for pivoting arrays into a normal relation."),
        ("INTERMEDIATE", "Which function evaluates a JSONPath expression against a jsonb value?", ["jsonb_apply", "jsonb_query", "jsonb_extract", "jsonb_path_query"], "D", "jsonb_path_query(doc, '$.items[*].price') evaluates a JSONPath expression and returns the matching values."),
        ("INTERMEDIATE", "Which operator removes a key from a jsonb object?", ["-", "--", "~", "!"], "A", "jsonb - 'key' returns the object with that key removed, and the same minus operator can remove array elements by index."),
        ("INTERMEDIATE", "Which function converts an array into a single delimiter-separated string?", ["string_to_array", "array_to_string", "unnest", "array_position"], "B", "array_to_string(array, ',') joins the elements with the given delimiter and is the inverse of string_to_array."),
        ("INTERMEDIATE", "Which aggregate function collects the values of a group into an array?", ["array_collect", "unnest", "array_agg", "json_agg"], "C", "array_agg(value) builds an array from all values in the group, such as array_agg(name ORDER BY age)."),
        ("INTERMEDIATE", "Which operator merges two jsonb objects into one?", ["+", "&", "->", "||"], "D", "The || operator merges jsonb objects, with values from the right operand overwriting duplicate keys from the left."),
        ("ADVANCED", "When should you prefer the jsonb_path_ops GIN operator class over the default jsonb_ops class?", ["always, it is faster everywhere", "for pure containment queries with @>, where it can be several times faster", "never, it is deprecated", "only for numeric keys"], "B", "jsonb_path_ops builds a smaller index that is very efficient for @> containment checks, though it lacks the key-existence operators."),
        ("ADVANCED", "Why is a regular btree index on a jsonb column impossible in PostgreSQL?", ["jsonb has no = operator", "btree needs unique keys", "the jsonb type has no total linear ordering for btree to rely on", "jsonb cannot be indexed at all"], "C", "jsonb supports equality but not a total linear ordering, so PostgreSQL provides GIN and SP-GIST indexes for it rather than btree."),
        ("ADVANCED", "You query WHERE (data ->> 'age')::int > 30 on a large jsonb table. What is the most efficient way to speed it up?", ["add a GIN index on data", "add a btree index on data", "use a hash index on data", "create a functional btree index on ((data ->> 'age')::int)"], "D", "Because the query casts the extracted text, a functional index on the exact expression ((data ->> 'age')::int) matches the query and accelerates it."),
        ("ADVANCED", "What does jsonb do with duplicate keys when a document is parsed?", ["the last duplicate key wins and key order is not preserved", "it keeps all duplicates in an array", "it raises an error", "it keeps only the first key"], "A", "jsonb stores keys in a sorted internal form where only the last occurrence of a duplicate key is kept, so textual order is lost but lookups are fast."),
        ("ADVANCED", "Given arr = ARRAY[10,20,30,40], what does arr[2:3] evaluate to?", ["[10,20]", "[20,30]", "[30,40]", "[40,10]"], "B", "Array slicing arr[2:3] selects the elements from index 2 through index 3 inclusive, so the array [10,20,30,40] yields [20,30]."),
        ("ADVANCED", "A json column stores an object that differs from another one only by whitespace. Why does an equality comparison return false?", ["jsonb ignores spaces too", "equality never works on json", "the json type compares raw bytes, so whitespace makes the values unequal", "the server normalizes text automatically"], "C", "The json type preserves the exact input text, so byte-for-byte comparisons fail when formatting differs; jsonb would normalize and match."),
        ("ADVANCED", "Given a jsonb value whose items key holds the array [5,7,9], what does data -> 'items' ->> 0 return?", ["7", "9", "null", "5"], "D", "data -> 'items' gives the jsonb array [5,7,9], and applying ->> 0 extracts element index 0 as text, which is 5."),
        ("ADVANCED", "Which statement is true about the key ordering of a jsonb object?", ["keys are stored in sorted order, not insertion order", "keys keep insertion order", "keys are stored in a hash", "order always matches the input exactly"], "A", "jsonb reorders keys into a sorted internal form for fast lookup, so the visible order does not match the insertion order of the input."),
        ("ADVANCED", "Which construct converts a whole table row into a jsonb value?", ["jsonb_from_row", "to_jsonb(row)", "jsonb(row)", "CAST row AS json"], "B", "to_jsonb(value) converts any SQL value, including an entire row, into a jsonb representation."),
        ("ADVANCED", "Why does the ? key-existence operator on a GIN index behave differently from using ->> on a plain text column?", ["it is always slower", "the ? operator only works on arrays", "the ? check can use the GIN index for key membership, while ->> is a plain extraction that needs an expression index", "? ignores the index"], "C", "The ? existence operator is directly supported by the GIN jsonb index, whereas ->> is just an extraction that requires a functional index to be accelerated."),
    ],
    44: [
        ("BEGINNER", "Which clause defines the window of rows that a window function operates over?", ["OVER", "PARTITION BY", "GROUP BY", "ROWS"], "A", "The OVER clause defines the partitioning and ordering of rows for a window function."),
        ("BEGINNER", "Which window function assigns a unique number to each row in the result set?", ["RANK", "ROW_NUMBER", "DENSE_RANK", "NTILE"], "B", "ROW_NUMBER() assigns a distinct sequential number to each row following the window order."),
        ("BEGINNER", "What is the main difference between RANK and ROW_NUMBER?", ["they are identical", "RANK cannot use ORDER BY", "RANK gives tied rows the same rank and skips positions, while ROW_NUMBER always increments by one", "ROW_NUMBER does not need ORDER BY"], "C", "RANK gives equal values the same rank and leaves gaps, whereas ROW_NUMBER always returns consecutive numbers even for ties."),
        ("BEGINNER", "What does PARTITION BY do inside an OVER clause?", ["sorts the rows", "limits the rows returned", "creates a new table", "divides rows into groups that the window function resets within"], "D", "PARTITION BY splits the result into groups, and the window function restarts its computation for each partition."),
        ("BEGINNER", "Which function ranks rows with equal values having the same rank but WITHOUT leaving gaps?", ["DENSE_RANK", "RANK", "ROW_NUMBER", "LAG"], "A", "DENSE_RANK assigns identical ranks to ties and does not skip numbers, so the ranks are always consecutive."),
        ("BEGINNER", "How does a window function differ from a plain aggregate?", ["there is no difference", "a window function returns one result per row while an aggregate collapses a group into one row", "aggregates always run faster", "windows cannot use SUM"], "B", "Aggregates reduce a group to a single row, while window functions keep all rows and attach the computed value to each of them."),
        ("BEGINNER", "What does ORDER BY inside an OVER clause control?", ["the order rows are inserted", "the primary key", "the order in which the window function processes rows", "permissions"], "C", "ORDER BY in OVER determines the row order used for ranking and running aggregates within each window."),
        ("BEGINNER", "Which function lets you access the value of a previous row in the same window?", ["LEAD", "ROW_NUMBER", "FIRST_VALUE", "LAG"], "D", "LAG(column) returns the value from the row that comes before the current row in the window order."),
        ("BEGINNER", "Which expression computes a running total over all rows up to and including the current row?", ["SUM(amount) OVER (ORDER BY day)", "SUM(amount)", "SELECT running", "COUNT(*) GROUP BY day"], "A", "SUM(amount) OVER (ORDER BY day) is a cumulative sum, so each row shows the running total as the frame grows with the current row."),
        ("BEGINNER", "Why can a window function not be used directly in a WHERE clause?", ["it is too slow", "WHERE is evaluated before the window function, which runs after the row filter", "the syntax is not allowed", "window functions can run in WHERE"], "B", "Window functions are evaluated after WHERE filtering, so they cannot appear in WHERE; use a subquery or CTE to filter on their results."),
        ("INTERMEDIATE", "Given sales(dept, amount) with rows ('A',100), ('A',200), ('B',150), what does SELECT dept, SUM(amount) OVER (PARTITION BY dept) FROM sales return for the three rows?", ["100, 200, 150", "300, 150, 150", "300, 300, 150", "100, 300, 150"], "C", "SUM OVER (PARTITION BY dept) repeats the per-department total on every row of that partition, so both A rows show 300 and the B row shows 150."),
        ("INTERMEDIATE", "Given score(name, value) with rows ('x',10), ('y',20), ('z',10), what does DENSE_RANK() OVER (ORDER BY value) yield for x, y and z?", ["1, 2, 3", "2, 1, 2", "3, 2, 3", "1, 2, 1"], "D", "DENSE_RANK gives both 10s the rank 1 and the next distinct value 20 the rank 2, producing 1, 2, 1 across x, y and z."),
        ("INTERMEDIATE", "Given the same score table, what does RANK() OVER (ORDER BY value) yield for x(10), y(20) and z(10)?", ["1, 3, 1", "1, 2, 2", "2, 3, 2", "1, 2, 1"], "A", "RANK ranks both 10s as 1 and then skips to 3 for the next value, so y receives 3, giving the sequence 1, 3, 1."),
        ("INTERMEDIATE", "What does LAG(salary) OVER (ORDER BY salary) return for the FIRST row of the window?", ["0", "NULL", "the same value", "an error"], "B", "LAG returns NULL for rows that have no previous row in the window order, such as the very first row."),
        ("INTERMEDIATE", "Which function returns the value from a row that follows the current row in the window?", ["LAG", "ROW_NUMBER", "LEAD", "LAST_VALUE"], "C", "LEAD(column) fetches the value from the row that comes after the current row in the window order."),
        ("INTERMEDIATE", "Given emp(name, dept, sal) with rows ('a','IT',10), ('b','IT',20), ('c','HR',30), what does COUNT(*) OVER (PARTITION BY dept) return per row?", ["1, 1, 1", "2, 1, 1", "3, 2, 1", "2, 2, 1"], "D", "The IT partition has two rows so its count is 2 on both IT rows, and the HR partition has one row so its count is 1, giving 2, 2, 1."),
        ("INTERMEDIATE", "Which function divides the ordered result set into a given number of roughly equal buckets?", ["NTILE(n)", "RANK()", "PERCENT_RANK()", "CUME_DIST()"], "A", "NTILE(n) assigns each row a bucket number from 1 to n, splitting the ordered set into n groups of near-equal size."),
        ("INTERMEDIATE", "What does the frame clause ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW define?", ["a partition", "a frame that starts at the first row of the partition and ends at the current row", "a new table", "an ordering"], "B", "That frame clause makes the window cover every row from the start of the partition through the current row, which is the basis of running totals."),
        ("INTERMEDIATE", "Given a running-total query SUM(x) OVER (ORDER BY pos), which frame is used implicitly when none is specified?", ["RANGE BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING", "no frame at all", "RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW", "ROWS BETWEEN CURRENT ROW AND CURRENT ROW"], "C", "When ORDER BY is present but no frame is written, the default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW."),
        ("INTERMEDIATE", "Which pair of functions returns the first and last values of a window frame?", ["LAG and LEAD", "ROW_NUMBER and RANK", "SUM and AVG", "FIRST_VALUE and LAST_VALUE"], "D", "FIRST_VALUE returns the value from the first row of the frame and LAST_VALUE returns the value from the last row of the frame."),
        ("ADVANCED", "Given daily prices (day, price) with rows (1,10), (2,12), (3,15), what does AVG(price) OVER (ORDER BY day ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) return?", ["10, 10, 11", "10, 11, 13.5", "10, 12, 15", "11, 13.5, 15"], "B", "The frame includes only the current and previous row, so the averages are 10, (10+12)/2 = 11 and (12+15)/2 = 13.5."),
        ("ADVANCED", "Given scores of 90, 90 and 70, what does CUME_DIST() OVER (ORDER BY score DESC) return for the row with score 70?", ["0", "0.5", "1", "0.75"], "C", "CUME_DIST is the count of rows up to and including the current one divided by the partition size; the lowest score is the last row, giving 3/3 = 1."),
        ("ADVANCED", "Which statement correctly contrasts RANGE frames with ROWS frames?", ["they are always identical", "RANGE counts physical rows", "ROWS cannot be used with ORDER BY", "RANGE treats rows with equal ORDER BY keys as one peer group, while ROWS counts individual rows"], "D", "RANGE frames group rows with equal ORDER BY keys into peers and move as a unit, whereas ROWS frames advance strictly by individual row count."),
        ("ADVANCED", "Given emp(name, sal) with rows ('a',50), ('b',50), ('c',60), what is the exact output of SELECT name, DENSE_RANK() OVER (ORDER BY sal) FROM emp ORDER BY name?", ["a 1, b 1, c 2", "a 1, b 2, c 3", "a 2, b 1, c 1", "a 1, b 1, c 3"], "A", "Both 50s tie for rank 1 and DENSE_RANK does not skip, so the 60 gets rank 2; ordered by name the rows are a 1, b 1, c 2."),
        ("ADVANCED", "Why can you not filter on a window function result with WHERE on the same query level?", ["window functions are not allowed in SQL", "WHERE runs before the window function has computed its values, so the predicate cannot see them", "the optimizer removes such filters", "it returns NULL"], "B", "WHERE filters rows before window functions evaluate, so a window result cannot be referenced there; wrap the query in a subquery or CTE to filter on it."),
        ("ADVANCED", "How do you avoid repeating long OVER clauses when a query needs several identical window definitions?", ["use a macro", "use GROUP BY", "use the WINDOW clause to name a window and reference it with OVER w", "there is no way"], "C", "The WINDOW clause names a window definition that later OVER references can reuse, cutting down on duplication in the query."),
        ("ADVANCED", "Given sales(region, amount) with rows ('N',10), ('N',5), ('S',8), what does LAG(amount, 1, 0) OVER (PARTITION BY region ORDER BY amount) return per row when rows are listed by increasing amount?", ["10, 5, 8", "0, 10, 0", "0, 10, 8", "0, 5, 0"], "D", "LAG with a default of 0 fills the first row of each partition with 0 and returns the previous amount for later rows, giving 0, 5, 0."),
        ("ADVANCED", "Why might SUM(amount) OVER (ORDER BY id) not give the expected running total when id values repeat?", ["with RANGE as the default frame, duplicate ids are treated as peers and grouped into one frame step", "SUM is not a window function", "ORDER BY cannot be used here", "duplicates are removed"], "A", "Because the default frame is RANGE, rows sharing the same id are included or excluded together, so the cumulative sum can jump; adding a unique tiebreaker fixes it."),
        ("ADVANCED", "Which approach keeps only the top 3 rows of each group after ranking?", ["GROUP BY with LIMIT 3", "a subquery that computes ROW_NUMBER() OVER (PARTITION BY grp ORDER BY score DESC) and an outer WHERE rn <= 3", "ORDER BY score LIMIT 3", "a single WHERE rn <= 3 directly"], "B", "Row numbering inside each partition followed by an outer filter rn <= 3 keeps exactly the top three rows of every group."),
        ("ADVANCED", "What is the relationship between ROW_NUMBER() and NTILE() results when ORDER BY values tie?", ["none, they are identical", "NTILE assigns unique numbers", "ROW_NUMBER breaks ties arbitrarily while NTILE groups tied rows possibly into different buckets without reordering them", "NTILE is deterministic while ROW_NUMBER is not"], "C", "ROW_NUMBER hands out arbitrary but unique numbers across ties, whereas NTILE assigns bucket numbers based on position, which can place equal values in different buckets."),
    ],
    45: [
        ("BEGINNER", "Which procedural language ships with PostgreSQL by default for writing stored functions?", ["PL/pgSQL", "PL/SQL", "Transact-SQL", "SQL/PSM"], "A", "PL/pgSQL is PostgreSQL's built-in procedural language used for functions, triggers and DO blocks."),
        ("BEGINNER", "In PL/pgSQL, what is the purpose of the dollar-quoted string $$ ... $$ around a function body?", ["to mark comments", "to delimit the function body so internal quotes need no escaping", "to concatenate strings", "to name parameters"], "B", "Dollar quoting wraps the function body in a delimiter, so single quotes inside it do not need escaping."),
        ("BEGINNER", "Which command writes a message to the server log from inside a PL/pgSQL function?", ["PRINT", "LOG", "RAISE", "ECHO"], "C", "RAISE NOTICE '...' writes a message and RAISE EXCEPTION aborts the function after reporting the error."),
        ("BEGINNER", "Which keyword starts the variable declaration section of a PL/pgSQL block?", ["VAR", "LET", "LOCAL", "DECLARE"], "D", "Variables are declared in a DECLARE section that precedes the BEGIN...END body of a PL/pgSQL block."),
        ("BEGINNER", "What is a common table expression (CTE) in PostgreSQL?", ["a named temporary result set defined with WITH", "a stored procedure", "an index type", "a transaction"], "A", "A common table expression, introduced by WITH name AS (...), names a subquery that the main query can reference."),
        ("BEGINNER", "Which clause must be present so that a CTE may reference itself recursively?", ["NO CYCLE", "RECURSIVE", "LOOP", "ROWS"], "B", "A self-referencing CTE must be declared WITH RECURSIVE for PostgreSQL to permit recursion."),
        ("BEGINNER", "Which statement creates a trigger on a table?", ["TRIGGER name", "NEW TRIGGER", "CREATE TRIGGER name BEFORE INSERT ON t ...", "ADD TRIGGER"], "C", "CREATE TRIGGER associates a trigger function with a table and specifies the timing (BEFORE/AFTER) and event (INSERT/UPDATE/DELETE)."),
        ("BEGINNER", "Which command installs an extension such as pg_trgm into the current database?", ["INSTALL EXTENSION", "USE EXTENSION", "ADD EXTENSION", "CREATE EXTENSION"], "D", "CREATE EXTENSION pg_trgm; loads the extension's SQL objects into the current database."),
        ("BEGINNER", "What does the PostGIS extension add to PostgreSQL?", ["geographic objects and spatial functions", "full-text search", "JSON parsing", "encryption"], "A", "PostGIS provides geometry types and spatial operations for geographic information systems."),
        ("BEGINNER", "What does the pg_trgm extension specialize in?", ["time-series data", "trigram-based text similarity and fuzzy matching", "encryption", "array handling"], "B", "pg_trgm builds trigram indexes on text and supports similarity operators such as % and <-> for fuzzy searches."),
        ("INTERMEDIATE", "Given a PL/pgSQL function declared RETURNS integer whose body is RETURN 2 + 3;, what does calling it return?", ["2", "3", "5", "null"], "C", "RETURN 2 + 3; evaluates the expression and returns the value 5, matching the RETURNS integer declaration."),
        ("INTERMEDIATE", "What must a row-level trigger function return to let the row change proceed?", ["an integer", "a boolean", "NULL only", "the special value NEW or OLD"], "D", "A row-level trigger function must return the NEW (or OLD) record to indicate which row to use, and returning NULL cancels the operation."),
        ("INTERMEDIATE", "When is a BEFORE trigger fired relative to the data-modifying command?", ["before the row is inserted, updated or deleted", "after commit", "before the transaction starts", "only on SELECT"], "A", "BEFORE triggers run before the row change is applied, allowing the trigger to modify NEW before it is stored."),
        ("INTERMEDIATE", "In a row-level trigger, what do NEW and OLD refer to?", ["the trigger function name", "NEW is the new row and OLD is the previous row", "two tables", "nothing"], "B", "NEW holds the incoming row for INSERT/UPDATE and OLD holds the prior row for UPDATE/DELETE, with the unused one being NULL."),
        ("INTERMEDIATE", "Why does a non-recursive CTE that references itself fail to parse?", ["it is a syntax error always", "CTEs are materialized", "a plain CTE cannot reference itself, and only WITH RECURSIVE permits self-reference", "you need a view"], "C", "A non-recursive CTE cannot reference itself in its definition; only WITH RECURSIVE enables self-reference."),
        ("INTERMEDIATE", "Which keyword must separate the base case and the recursive step of a recursive CTE?", ["UNION", "INTERSECT", "MINUS", "UNION ALL"], "D", "WITH RECURSIVE combines the anchor term with the recursive term using UNION ALL (or UNION)."),
        ("INTERMEDIATE", "With pg_trgm installed, which operator tests whether two strings are similar based on trigram similarity?", ["%", "~", "LIKE", "="], "A", "The % operator returns true when the trigram similarity between two strings exceeds the pg_trgm similarity threshold."),
        ("INTERMEDIATE", "What does CREATE EXTENSION IF NOT EXISTS pg_trgm; do when the extension is already installed?", ["raises an error", "does nothing and continues", "drops the extension", "creates a duplicate"], "B", "The IF NOT EXISTS clause makes the command a no-op when the extension is already present instead of raising an error."),
        ("INTERMEDIATE", "Which PL/pgSQL construct conditionally runs one block of code or another?", ["SWITCH", "CASE WHEN THEN", "IF ... THEN ... ELSE ... END IF;", "LOOP"], "C", "PL/pgSQL branches with IF ... THEN ... ELSE ... END IF (and CASE) to run different code depending on a condition."),
        ("INTERMEDIATE", "Which volatility setting tells the planner that a function returns the same result for identical arguments and can be optimized away?", ["VOLATILE", "STABLE", "EXTERNAL", "IMMUTABLE"], "D", "IMMUTABLE means the function cannot change its result for fixed inputs, enabling constant folding and index usage, while STABLE is only safe within one statement."),
        ("ADVANCED", "WITH RECURSIVE nums(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM nums WHERE n < 5) SELECT max(n) FROM nums; What does this return?", ["4", "5", "6", "infinite loop"], "B", "The recursion adds 1 at each step until n reaches 5, at which point n < 5 is false, so the rows are 1..5 and max(n) is 5."),
        ("ADVANCED", "Which PL/pgSQL trigger function correctly blocks a row when the quantity is negative?", ["CREATE FUNCTION chk() RETURNS TRIGGER AS $$ BEGIN IF NEW.qty < 0 THEN RAISE EXCEPTION 'negative qty'; END IF; RETURN NEW; END $$ LANGUAGE plpgsql;", "CREATE FUNCTION chk() RETURNS integer AS $$ RETURN 0; $$ LANGUAGE plpgsql;", "CREATE FUNCTION chk() RETURNS TRIGGER AS $$ SELECT 1; $$ LANGUAGE sql;", "CREATE FUNCTION chk() RETURNS trigger AS $$ BEGIN RETURN NULL; END $$ LANGUAGE plpgsql;"], "A", "The function checks NEW.qty and raises an exception for negative values; otherwise it returns NEW, and because it returns NEW the row change is allowed to proceed."),
        ("ADVANCED", "Which PostGIS function constructs a geometry from a well-known text (WKT) string?", ["ST_Buffer", "ST_Intersects", "ST_Transform", "ST_GeomFromText"], "D", "ST_GeomFromText('POINT(1 2)') parses a well-known text string into a PostGIS geometry value."),
        ("ADVANCED", "How do you remove a trigger named trg from table t?", ["DROP TRIGGER trg ON t;", "DELETE TRIGGER trg;", "REMOVE trg;", "DROP TRIGGER t ON trg;"], "A", "DROP TRIGGER trg ON t; removes the trigger from the table, and you may add IF EXISTS or CASCADE."),
        ("ADVANCED", "Inside a PL/pgSQL function, what is the difference between PERFORM and a bare SELECT?", ["there is no difference", "a bare SELECT must assign its result to INTO, while PERFORM runs a query and discards the result", "PERFORM is only for INSERT", "SELECT is not allowed"], "B", "Inside PL/pgSQL a bare SELECT must send its output into variables with INTO, whereas PERFORM executes a query purely for its side effects and discards any output."),
        ("ADVANCED", "Which index helps a query like WHERE name % 'jhon' that uses pg_trgm similarity?", ["btree on name", "hash on name", "a GIN or GiST trigram index on name", "no index helps"], "C", "pg_trgm provides GIN and GiST operator classes that accelerate % similarity and ILIKE-style matching on text columns."),
        ("ADVANCED", "A recursive CTE has an anchor that selects employees whose manager_id IS NULL and a recursive step that joins employee to the CTE on manager_id. What does the whole CTE compute?", ["only employees without managers", "a single employee", "nothing", "the full employee reporting hierarchy from the top down"], "D", "The anchor selects the root employees and the recursive step walks down the manager_id links, producing the entire reporting tree."),
        ("ADVANCED", "Which SECURITY setting makes a function execute with the privileges of its creator rather than the caller?", ["SECURITY DEFINER", "SECURITY INVOKER", "SECURITY OWNER", "SECURITY CALLER"], "A", "SECURITY DEFINER runs the function as the function owner, which can deliberately escalate privileges for controlled access."),
        ("ADVANCED", "Why can a STABLE function not be used in a btree index expression?", ["it never runs", "it cannot; only IMMUTABLE functions may appear in index expressions", "STABLE always returns constants", "there is no restriction"], "B", "Indexes require functions that always produce the same value for the same input, a guarantee that only IMMUTABLE functions provide; STABLE is not sufficient."),
        ("ADVANCED", "WITH RECURSIVE t(n) AS (VALUES (1) UNION ALL SELECT n + 2 FROM t WHERE n < 6) — how many rows does t contain?", ["3", "6", "4", "5"], "C", "Starting from 1 and adding 2 while n < 6 produces the values 1, 3, 5 and then 7, so the CTE contains exactly 4 rows."),
    ],
}
